#include "../../02-数据结构/可回滚并查集与时间线段树.cpp"
vector<int> dynamic_connectivity(int arg_n,const vector<array<int,3>> &arg_ops){n=arg_n;ops=arg_ops;return dynamic_connectivity();}
int main(){RollbackDSU d(5);d.merge(1,2);int t=d.snapshot();d.merge(2,3);d.merge(4,5);d.merge(3,5);d.rollback(t);assert(d.find(1)==d.find(2)&&d.find(1)!=d.find(3)&&d.find(4)!=d.find(5));assert(dynamic_connectivity(0,{}).empty());mt19937 g(124);for(int z=0;z<300;z++){int n=1+g()%12;map<pair<int,int>,int> cnt;vector<array<int,3>>ops;vector<int>exp;for(int i=0;i<150;i++){int u=1+g()%n,v=1+g()%n;if(u>v)swap(u,v);int type=g()%3;if(type==1&&!cnt[{u,v}])type=0;ops.push_back({type,u,v});if(type==0)cnt[{u,v}]++;else if(type==1)cnt[{u,v}]--;else{vector<int>vis(n+1);queue<int>q;q.push(u);vis[u]=1;while(!q.empty()){int a=q.front();q.pop();for(auto [e,c]:cnt)if(c){int b=e.first==a?e.second:e.second==a?e.first:0;if(b&&!vis[b])vis[b]=1,q.push(b);}}exp.push_back(vis[v]);}}assert(dynamic_connectivity(n,ops)==exp);}cout<<"rollback OK\n";}
